package main

import (
	"fmt"
)

func main() {
	var s string
	var n int
	fmt.Scan(&s)
	fmt.Scan(&n)

	strBytes := []byte(s)
	strLen := len(strBytes)

	check := func(a int) bool {
		for i := 1; i <= a-n; i++ {
			if strBytes[strLen-i] != strBytes[strLen-i-a] {
				return false
			}
		}
		return true
	}

	minVal, maxVal := 0, 0
	if n > strLen {
		minVal = (strLen + n) / 2
	} else {
		minVal = n
	}
	maxVal = (strLen + n) / 2

	temp := 0
	for i := 0; i < strLen; i++ {
		for j := 1; j*2+i <= strLen; j++ {
			key := true
			for k := 1; k <= j; k++ {
				if strBytes[i+k-1] != strBytes[i+k+j-1] {
					key = false
					break
				}
			}
			if key && j > temp {
				temp = j
			}
		}
	}

	ans := 0
	for i := maxVal; i >= minVal && ans == 0; i-- {
		if check(i) {
			ans = i
		}
	}

	if minVal > ans {
		ans = minVal
	}
	if temp > ans {
		ans = temp
	}

	fmt.Print(2 * ans)
}

